/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: setup, enter
 * Tests
 *   - MOV original admission, unknown transfer and processing/publication retries keep one source upload
 *   - original upload shows measured completion while a real receiver has not yet confirmed the source
 *   - server validation displays the measured current-step percentage and keeps unknown progress indeterminate
 *   - Album lookup dismisses without losing its choice and the production Video form is accessible at 320 px
 *   - workbench retains Album upload and MP3 conversion beside Video, while unavailable storage is explicit
 *   - an ordinary account never reads or opens private Video projects
 * @end-catalog */

import { expect, test, type Page } from '@playwright/test';
import { createServer } from 'node:http';
import AxeBuilder from '@axe-core/playwright';
import sharp from 'sharp';
import { capabilities, session, viewer } from '../src/features/admin/adminFixtures.testSupport';
import { catalogAlbum } from '../src/features/admin/catalogReviewFixtures.testSupport';
import { videoProject, videoProjectId } from '../src/features/admin/videoUploadFixtures.testSupport';
import type { VideoProject } from '../src/features/admin/videoUploadApi';

/** Browser gate uses the built app and real CSP, with synthetic server lifecycle transitions kept explicit. */
async function setup(page: Page, options: { fresh?: boolean; admin?: boolean; available?: boolean } = {}) {
  let item = videoProject();
  const writes: Array<{ path: string; body: any }> = [], uploads: string[] = [];
  let publications = 0, privateReads = 0;
  if (options.fresh) {
    item.stage = 'prepare'; item.source.status = 'idle'; item.source.operationId = null;
    item.processing = { state: 'idle', plan: 'pending', step: null, progress: null, issue: null, facts: null };
    item.approvalDigest = null;
  }
  const headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };
  const cover = await sharp({ create: { width: 160, height: 90, channels: 3, background: '#247040' } }).jpeg().toBuffer();
  const coverId = 'cccccccccccccccccccccccc';
  const ready = () => {
    item.stage = 'review'; item.source.status = 'ready'; item.processing = videoProject().processing;
    item.covers = [{ id: coverId, operationId: '20000000-0000-4000-8000-000000000001', name: 'Embedded thumbnail.jpg', source: 'embedded', state: 'ready', previewUrl: `/api/admin/v1/video-projects/${item.id}/covers/${coverId}/preview?viewer=${viewer}` }];
    item.selectedCoverId = coverId; item.approvalDigest = 'vp_' + 'a'.repeat(64);
  };
  await page.route('**/auth/browser/session', route => route.fulfill({ json: { user: { ...session.user, role: options.admin === false ? 'user' : 'admin' } } }));
  await page.route('**/api/listener/v1/capabilities', route => route.fulfill({ json: { playlists: false } }));
  await page.route('**/api/listener/v1/personalization-capabilities', route => route.fulfill({ json: { contractVersion: 1, deterministicDiscovery: false, artistFollows: false } }));
  await page.route('**/api/listener/v1/home', route => route.fulfill({ json: { title: 'Synthetic Home', sections: [] } }));
  await page.route('**/content/me/playlists?limit=50', route => route.fulfill({ json: { items: [], nextCursor: null }, headers }));
  await page.route('**/api/admin/v1/**', async route => {
    const request = route.request(), url = new URL(request.url()), path = url.pathname;
    privateReads++;
    if (!path.endsWith('/preview')) expect(request.headers()['x-finitude-account-viewer']).toBe(viewer);
    if (path.endsWith('/capabilities')) return route.fulfill({ json: { ...capabilities, catalog: { editing: true, visibility: true }, localMp3Conversion: { enabled: true, readSources: true, replace: true, preset: 'mp3-320', maxFiles: 100 }, videoUploads: { enabled: options.available !== false, maxFileBytes: 512 * 1024 ** 2, acceptedExtensions: ['mp4', 'mov', 'm4v'] } }, headers });
    if (path.endsWith('/preview')) return route.fulfill({ body: cover, contentType: 'image/jpeg', headers });
    if (path === '/api/admin/v1/catalog/album') return route.fulfill({ json: { items: [catalogAlbum()], nextCursor: null }, headers });
    if (path === `/api/admin/v1/catalog/album/${catalogAlbum().id}`) return route.fulfill({ json: { item: catalogAlbum() }, headers });
    if (path === '/api/admin/v1/video-projects' && request.method() === 'GET') return route.fulfill({ json: { schemaVersion: 1, items: [item], nextCursor: null }, headers });
    if (path.endsWith('/source') && request.method() === 'POST') {
      const operationId = request.headers()['idempotency-key']; uploads.push(operationId);
      item = { ...item, stage: 'upload', revision: item.revision + 1, source: { ...item.source, status: 'unknown', operationId } };
      return route.fulfill({ json: { schemaVersion: 1, item, receipt: { operationId, revision: item.revision } }, headers });
    }
    if (request.method() === 'POST' || request.method() === 'PATCH') {
      const body = request.postDataJSON(); writes.push({ path, body }); item.revision++;
      if (path === '/api/admin/v1/video-projects') {
        item.source.filename = body.filename; item.source.byteLength = body.byteLength;
      } else if (request.method() === 'PATCH') {
        item.draft = { ...item.draft, ...body.patch };
        if (item.draft.albumId) { const album = catalogAlbum(); item.references.album = { id: album.id, title: 'Synthetic catalog Album', revision: album.revision, visibility: album.visibility, coverUrl: null }; }
        item.approvalDigest = 'vp_' + String(item.revision).padStart(64, 'a');
      } else if (path.endsWith('/source/reconcile')) {
        expect(body.operationId).toBe(item.source.operationId); item.source.status = 'ready'; item.stage = 'validate';
        item.processing = { state: 'failed', plan: 'pending', step: 'validate', progress: null, issue: 'processor_unavailable', facts: null };
      } else if (path.endsWith('/processing/retry')) ready();
      else if (path.endsWith('/publish')) {
        expect(body.expectedRevision).toBe(item.revision - 1); expect(body.approvalDigest).toBe(item.approvalDigest);
        publications++; item.publication = { ...item.publication, state: 'failed', issue: 'storage_unknown', operationId: body.operationId }; item.stage = 'publish';
      } else if (path.endsWith('/publication/retry')) {
        expect(body.operationId).toBe(item.publication.operationId);
        item.stage = 'complete'; item.publication = { ...item.publication, state: 'complete', mediaTrackId: 'dddddddddddddddddddddddd', issue: null, cleanupPending: true };
      } else if (path.endsWith('/cleanup')) item.publication.cleanupPending = false;
      return route.fulfill({ json: { schemaVersion: 1, item, ...(!path.endsWith('/source/reconcile') && !path.endsWith('/publication/retry') ? { receipt: { operationId: body.operationId, revision: item.revision } } : {}) }, headers });
    }
    return route.fulfill({ json: { schemaVersion: 1, item }, headers });
  });
  return { writes, uploads, ready, current: () => item, publications: () => publications, privateReads: () => privateReads,
    set(next: VideoProject) { item = next; } };
}

async function enter(page: Page, path = `/finitude/admin/videos/${videoProjectId}`) {
  await page.goto(path); await page.getByRole('button', { name: 'Switch to Admin view', exact: true }).click();
  await expect(page.getByRole('heading', { name: 'Upload Video', exact: true })).toBeVisible();
}

test('MOV original admission, unknown transfer and processing/publication retries keep one source upload', async ({ page }) => {
  const flow = await setup(page, { fresh: true }); await enter(page, '/finitude/admin/videos/new');
  await page.locator('input[type=file]').setInputFiles({ name: 'synthetic-original.MOV', mimeType: 'video/quicktime', buffer: Buffer.from('not-a-movie!') });
  await expect(page).toHaveURL(new RegExp(`/videos/${videoProjectId}$`));
  expect(flow.uploads).toHaveLength(0);
  await page.getByRole('button', { name: 'Preview local video', exact: true }).click();
  await expect(page.getByRole('dialog')).toContainText('This device cannot preview the video');
  await page.getByRole('dialog').getByRole('button', { name: 'Cancel', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Upload original video', exact: true })).toBeEnabled();
  await page.getByRole('button', { name: 'Upload original video', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Reconcile original upload', exact: true })).toBeEnabled();
  await expect(page.locator('input[accept*="video/quicktime"]')).toBeDisabled(); expect(flow.uploads).toHaveLength(1);
  await page.getByRole('button', { name: 'Reconcile original upload', exact: true }).click();
  await page.getByRole('button', { name: 'Retry processing · no re-upload', exact: true }).click();
  await expect(page.getByAltText('Selected Video cover')).toBeVisible();
  await page.getByLabel('Video title', { exact: true }).fill('Confirmed personal Video');
  await page.getByLabel('Public byline (optional)', { exact: true }).fill('Explicit signature');
  await page.getByRole('button', { name: 'Review and publish', exact: true }).click();
  const dialog = page.getByRole('dialog', { name: 'Confirm Video publication' });
  await expect(dialog).toContainText('Confirmed personal Video'); await expect(dialog).toContainText('Explicit signature');
  await expect(dialog.getByAltText('Selected Video cover')).toBeVisible();
  await dialog.getByRole('button', { name: 'Cancel', exact: true }).click(); expect(flow.publications()).toBe(0);
  await page.getByRole('button', { name: 'Review and publish', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Confirm publication', exact: true }).click();
  await page.getByRole('button', { name: 'Retry publication · no re-upload', exact: true }).click();
  await expect(page.getByText('Publication complete · temporary cleanup pending', { exact: true })).toBeVisible();
  expect(flow.uploads).toHaveLength(1); expect(flow.publications()).toBe(1);
  await page.getByRole('button', { name: 'Retry cleanup', exact: true }).click();
  await expect(page.getByText('Video publication complete', { exact: true })).toBeVisible();
});

test('original upload shows measured completion while a real receiver has not yet confirmed the source', async ({ page }, testInfo) => {
  const flow = await setup(page, { fresh: true });
  let releaseResponse!: () => void, confirmReceived!: () => void;
  const responseGate = new Promise<void>(resolve => { releaseResponse = resolve; });
  const received = new Promise<void>(resolve => { confirmReceived = resolve; });
  const operations: string[] = [];
  let byteLength = 0, receivedViewer: string | string[] | undefined;
  // The browser sends real bytes to a local receiver; only its receipt is held, so progress is not simulated.
  const receiver = createServer((request, response) => {
    request.on('data', (chunk: Buffer) => { byteLength += chunk.byteLength; });
    request.once('end', () => {
      const operationId = String(request.headers['idempotency-key']); operations.push(operationId);
      receivedViewer = request.headers['x-finitude-account-viewer'];
      confirmReceived();
      void responseGate.then(() => {
        const item = flow.current();
        const confirmed: VideoProject = { ...item, stage: 'validate', revision: item.revision + 1,
          source: { ...item.source, status: 'ready', operationId },
          processing: { ...item.processing, state: 'queued' } };
        flow.set(confirmed);
        response.writeHead(200, { 'Content-Type': 'application/json', 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' });
        response.end(JSON.stringify({ schemaVersion: 1, item: confirmed, receipt: { operationId, revision: confirmed.revision } }));
      });
    });
  });
  try {
    await new Promise<void>((resolve, reject) => { receiver.once('error', reject); receiver.listen(0, '127.0.0.1', resolve); });
    const address = receiver.address();
    if (!address || typeof address === 'string') throw new Error('The synthetic upload receiver did not bind a TCP port.');
    await page.route(`**/api/admin/v1/video-projects/${videoProjectId}/source`, route => route.continue({ url: `http://127.0.0.1:${address.port}/source` }));
    await enter(page, '/finitude/admin/videos/new');
    await page.locator('input[type=file]').setInputFiles({ name: 'synthetic-original.MOV', mimeType: 'video/quicktime', buffer: Buffer.from('not-a-movie!') });
    await expect(page).toHaveURL(new RegExp(`/videos/${videoProjectId}$`));
    await page.getByRole('button', { name: 'Upload original video', exact: true }).click();
    await received;
    const progress = page.getByRole('progressbar', { name: 'Transferring original bytes… Awaiting server confirmation.', exact: true });
    await expect(progress).toHaveAttribute('value', '100');
    await expect(page.getByText('100%', { exact: true })).toBeVisible();
    await expect(page.getByText('Bytes transferred. Waiting for server confirmation.', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Reconcile original upload', exact: true })).toBeDisabled();
    expect(receivedViewer).toBe(viewer); expect(byteLength).toBeGreaterThan(12); expect(operations).toHaveLength(1); expect(flow.current().source.status).toBe('idle');
    await page.screenshot({ path: testInfo.outputPath('video-upload-awaiting-receipt.png'), fullPage: true });
    releaseResponse();
    await expect(progress).toHaveCount(0);
    await expect.poll(() => flow.current().source.status).toBe('ready');
    expect(operations).toHaveLength(1);
  } finally {
    releaseResponse();
    receiver.closeAllConnections();
    await new Promise<void>((resolve, reject) => receiver.close(error => error ? reject(error) : resolve()));
  }
});

test('server validation displays the measured current-step percentage and keeps unknown progress indeterminate', async ({ page }, testInfo) => {
  const flow = await setup(page);
  flow.set({ ...flow.current(), stage: 'validate', approvalDigest: null,
    processing: { ...flow.current().processing, state: 'running', step: 'validate', progress: 37 } });
  await enter(page);
  const progress = page.getByRole('progressbar', { name: 'Server validation and adaptation', exact: true });
  await expect(page.getByText('Validating complete decoding', { exact: true })).toBeVisible();
  await expect(progress).toHaveAttribute('value', '37');
  await expect(page.getByText('37%', { exact: true })).toBeVisible();
  flow.set({ ...flow.current(), processing: { ...flow.current().processing, progress: 68 } });
  await expect(progress).toHaveAttribute('value', '68');
  await expect(page.getByText('68%', { exact: true })).toBeVisible();
  await expect(page.getByText('37%', { exact: true })).toHaveCount(0);
  await page.setViewportSize({ width: 320, height: 844 });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  const accessibility = await new AxeBuilder({ page }).analyze();
  expect(accessibility.violations.filter(issue => ['critical', 'serious'].includes(issue.impact ?? ''))).toEqual([]);
  await progress.scrollIntoViewIfNeeded();
  await page.screenshot({ path: testInfo.outputPath('video-server-progress-mobile.png'), fullPage: true });
  flow.set({ ...flow.current(), processing: { ...flow.current().processing, step: 'cover', progress: null } });
  await expect(page.getByText('Extracting default cover', { exact: true })).toBeVisible();
  await expect(progress).not.toHaveAttribute('value');
  await expect(page.getByText('68%', { exact: true })).toHaveCount(0);
});

test('Album lookup dismisses without losing its choice and the production Video form is accessible at 320 px', async ({ page }, testInfo) => {
  const flow = await setup(page); flow.ready(); await enter(page);
  const album = page.getByRole('combobox', { name: 'Album (optional)' });
  await album.click(); await page.getByRole('option', { name: /Synthetic catalog Album/ }).click();
  await expect(album).toHaveValue('Synthetic catalog Album'); await expect(album).toHaveAttribute('aria-expanded', 'false');
  await album.fill('Another query'); await album.press('Escape'); await expect(album).toHaveValue('Synthetic catalog Album');
  await album.click(); await page.getByRole('heading', { name: 'Publication details', exact: true }).click(); await expect(album).toHaveAttribute('aria-expanded', 'false');
  await album.click(); await album.press('Tab'); await page.keyboard.press('Tab'); await expect(album).toHaveAttribute('aria-expanded', 'false');
  await page.getByRole('button', { name: 'Review and publish', exact: true }).click();
  await expect(page.getByRole('dialog')).toContainText('Synthetic catalog Album');
  await page.getByRole('dialog').getByRole('button', { name: 'Cancel', exact: true }).click();
  const footer = page.locator('#main-content footer');
  const surface = await page.locator('#main-content').evaluate(element => getComputedStyle(element.parentElement!).backgroundColor);
  await expect(footer).toHaveCSS('background-color', surface);
  await expect(footer).toHaveCSS('position', 'sticky');
  await footer.scrollIntoViewIfNeeded();
  await page.screenshot({ path: testInfo.outputPath('video-form-desktop.png'), fullPage: true });
  await page.setViewportSize({ width: 320, height: 844 });
  await expect(footer).toHaveCSS('background-color', surface);
  await expect(footer).toHaveCSS('position', 'static');
  await footer.scrollIntoViewIfNeeded();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  const accessibility = await new AxeBuilder({ page }).analyze();
  expect(accessibility.violations.filter(issue => ['critical', 'serious'].includes(issue.impact ?? ''))).toEqual([]);
  await page.screenshot({ path: testInfo.outputPath('video-form-mobile.png'), fullPage: true });
});

test('workbench retains Album upload and MP3 conversion beside Video, while unavailable storage is explicit', async ({ page }) => {
  await setup(page, { available: false }); await page.goto('/finitude/admin/imports?source=videos');
  await page.getByRole('button', { name: 'Switch to Admin view', exact: true }).click();
  await expect(page.getByRole('link', { name: 'Upload new Album', exact: true })).toHaveAttribute('href', '/finitude/admin/imports/new');
  await expect(page.getByRole('link', { name: 'Local MP3 conversion', exact: true })).toHaveAttribute('href', '/finitude/admin/conversions');
  await expect(page.getByRole('button', { name: 'Upload Video', exact: true })).toBeDisabled();
  await expect(page.getByText('Video uploads are not available on this server.', { exact: true })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Synthetic Video', exact: true })).toBeVisible();
  await page.getByRole('button', { name: 'Current view: Admin' }).click();
  await page.getByRole('menuitemradio', { name: 'User', exact: true }).click();
  await expect(page.getByText('Synthetic Video', { exact: true })).toHaveCount(0);
});

test('an ordinary account never reads or opens private Video projects', async ({ page }) => {
  const flow = await setup(page, { admin: false }); await page.goto(`/finitude/admin/videos/${videoProjectId}`);
  await expect(page.getByRole('heading', { name: 'Workbench', exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Switch to Admin view', exact: true })).toHaveCount(0);
  await expect(page.getByRole('heading', { name: 'Synthetic Video', exact: true })).toHaveCount(0);
  expect(flow.privateReads()).toBe(0);
});
